/**
 * ARO IN-APP RESPONSIVE BROWSER PREVIEW (Phase 13, Slice 4)
 *
 * Feature flag: $aroFeatures.inAppBrowserPreview
 * Adapter: adapters.browserPreview (persisted in conductor.workspace.v3.browser.*)
 *
 * Provides embedded, multi-viewport live preview for web applications,
 * artifacts, and dev-servers generated by agents.
 */

import { useStore } from '@nanostores/react'
import { useCallback, useEffect, useState } from 'react'

import { $previewTabs, $previewViewport, adapters, type BrowserTab, type ViewportId } from '@/adapters'
import { normalizePreviewUrl } from '@/adapters/browser-preview'
import { cn } from '@/lib/utils'

import { $aroFeatures } from './flags'
import {
  IconCheck,
  IconCopy,
  IconExternal,
  IconEye,
  IconGlobe,
  IconMonitor,
  IconPlus,
  IconRefresh,
  IconX,
} from './Icons'
import { InlineHint, SourceBadge } from './live'
import { Button, Tip } from './ui'

function IconTablet({ size = 12, ...props }: React.SVGProps<SVGSVGElement> & { size?: number }) {
  return (
    <svg
      fill="none"
      height={size}
      stroke="currentColor"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={1.7}
      viewBox="0 0 24 24"
      width={size}
      {...props}
    >
      <rect height="18" rx="2" width="14" x="5" y="3" />
      <path d="M12 17h.01" />
    </svg>
  )
}

function IconSmartphone({ size = 12, ...props }: React.SVGProps<SVGSVGElement> & { size?: number }) {
  return (
    <svg
      fill="none"
      height={size}
      stroke="currentColor"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={1.7}
      viewBox="0 0 24 24"
      width={size}
      {...props}
    >
      <rect height="16" rx="2" width="10" x="7" y="4" />
      <path d="M12 17h.01" />
    </svg>
  )
}

export const VIEWPORTS: { icon: typeof IconMonitor | typeof IconTablet | typeof IconSmartphone; id: ViewportId; label: string; width: string }[] = [
  { icon: IconMonitor, id: 'desktop', label: 'Desktop', width: '100%' },
  { icon: IconTablet, id: 'tablet', label: 'Tablet (768px)', width: '768px' },
  { icon: IconSmartphone, id: 'mobile', label: 'Mobile (390px)', width: '390px' },
]

export const DEV_SERVER_PRESETS = [
  { label: ':3000', url: 'http://localhost:3000', hint: 'Next.js / CRA / Node' },
  { label: ':5173', url: 'http://localhost:5173', hint: 'Vite / Svelte / Solid' },
  { label: ':8080', url: 'http://localhost:8080', hint: 'Webpack / Vue / Java' },
  { label: ':4321', url: 'http://localhost:4321', hint: 'Astro' },
]

export interface AroBrowserPreviewProps {
  overrideTabs?: BrowserTab[]
  overrideViewport?: ViewportId
  forceEnabled?: boolean
  initialUrl?: string
  className?: string
}

export function AroBrowserPreview({
  overrideTabs,
  overrideViewport,
  forceEnabled,
  initialUrl,
  className,
}: AroBrowserPreviewProps) {
  const features = useStore($aroFeatures)
  const enabled = forceEnabled ?? features.inAppBrowserPreview

  const liveTabs = useStore($previewTabs)
  const liveViewport = useStore($previewViewport)

  const tabs = overrideTabs !== undefined ? overrideTabs : liveTabs
  const viewport = overrideViewport !== undefined ? overrideViewport : liveViewport

  const [activeId, setActiveId] = useState<string>(() => tabs[0]?.id ?? '')
  const activeTab = tabs.find((t) => t.id === activeId) ?? tabs[0] ?? adapters.browserPreview.makeTab(initialUrl)

  const [inputVal, setInputVal] = useState<string>(activeTab.input || initialUrl || '')
  const [reloadNonce, setReloadNonce] = useState(0)
  const [error, setError] = useState<string>('')
  const [copied, setCopied] = useState(false)

  useEffect(() => {
    if (tabs.length === 0 && overrideTabs === undefined) {
      const fresh = adapters.browserPreview.makeTab(initialUrl)
      adapters.browserPreview.saveTabs([fresh])
      setActiveId(fresh.id)
    }
  }, [tabs.length, overrideTabs, initialUrl])

  useEffect(() => {
    if (activeTab) {
      setInputVal(activeTab.input)
      setError('')
    }
  }, [activeTab])

  const handleOpenUrl = useCallback(
    (targetUrl?: string) => {
      const raw = (targetUrl ?? inputVal).trim()

      if (!raw) {
        return
      }

      const normalized = normalizePreviewUrl(raw)

      if (!normalized) {
        setError('Enter a valid HTTP or HTTPS URL.')

        return
      }

      setError('')

      let hostTitle = 'Preview'

      try {
        hostTitle = new URL(normalized).hostname.replace(/^www\./, '')
      } catch {
        hostTitle = normalized
      }

      const existing = tabs.find((t) => t.id === activeTab.id)
      const targetTab = existing ?? activeTab

      const updatedTab: BrowserTab = {
        ...targetTab,
        input: normalized,
        loading: true,
        title: hostTitle,
        url: normalized,
      }

      const updated = existing
        ? tabs.map((t) => (t.id === activeTab.id ? updatedTab : t))
        : [...tabs, updatedTab]

      if (overrideTabs === undefined) {
        adapters.browserPreview.saveTabs(updated)
      }

      setActiveId(updatedTab.id)
    },
    [inputVal, tabs, activeTab, overrideTabs],
  )

  const handleNewTab = useCallback(() => {
    const fresh = adapters.browserPreview.makeTab()
    const nextTabs = [...tabs, fresh]

    if (overrideTabs === undefined) {
      adapters.browserPreview.saveTabs(nextTabs)
    }

    setActiveId(fresh.id)
    setInputVal('')
    setError('')
  }, [tabs, overrideTabs])

  const handleCloseTab = useCallback(
    (id: string) => {
      const idx = tabs.findIndex((t) => t.id === id)

      if (idx === -1) {
        return
      }

      const rest = tabs.filter((t) => t.id !== id)

      if (rest.length === 0) {
        const fresh = adapters.browserPreview.makeTab()

        if (overrideTabs === undefined) {
          adapters.browserPreview.saveTabs([fresh])
        }

        setActiveId(fresh.id)
        setInputVal('')

        return
      }

      if (overrideTabs === undefined) {
        adapters.browserPreview.saveTabs(rest)
      }

      if (id === activeTab.id) {
        const nextActive = rest[Math.min(Math.max(0, idx - 1), rest.length - 1)]
        setActiveId(nextActive.id)
        setInputVal(nextActive.input)
      }
    },
    [tabs, activeTab.id, overrideTabs],
  )

  const handleSetViewport = useCallback(
    (vp: ViewportId) => {
      if (overrideViewport === undefined) {
        adapters.browserPreview.setViewport(vp)
      }
    },
    [overrideViewport],
  )

  const handleReload = useCallback(() => {
    setReloadNonce((n) => n + 1)
  }, [])

  const handleCopyUrl = useCallback(() => {
    if (!activeTab.url) {
      return
    }

    navigator.clipboard?.writeText?.(activeTab.url).catch(() => {})
    setCopied(true)
    setTimeout(() => setCopied(false), 1500)
  }, [activeTab.url])

  if (!enabled) {
    return (
      <div className={cn('flex h-full min-h-0 flex-1 flex-col overflow-hidden font-aro-sans text-xs', className)} data-theme="obsidian">
        <header className="flex flex-wrap items-center gap-3 border-b border-aro-line-soft bg-aro-sunken/60 px-4 py-2.5">
          <div className="min-w-0">
            <div className="font-aro-mono text-[var(--aro-text-2xs,10px)] font-semibold tracking-[.14em] text-aro-ink-4 uppercase">web preview · viewport</div>
            <h1 className="text-sm font-semibold text-aro-ink">Browser Preview</h1>
          </div>
          <div className="ml-auto flex items-center gap-2">
            <SourceBadge demoLabel="disabled" live={false} />
          </div>
        </header>
        <div className="aro-scroll-thin flex flex-1 items-center justify-center overflow-y-auto p-6">
          <div className="max-w-[440px] space-y-3 text-center">
            <InlineHint>
              In-App Browser Preview is currently disabled by feature flag (<span className="font-aro-mono text-xs text-aro-iris">inAppBrowserPreview</span>). Enable it in Aro settings or feature flags.
            </InlineHint>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className={cn('flex h-full min-h-0 flex-1 flex-col overflow-hidden font-aro-sans text-xs', className)} data-theme="obsidian">
      {/* Tab Strip */}
      <div aria-label="Browser tabs" className="flex shrink-0 items-center gap-1 border-b border-aro-line-soft bg-aro-sunken/60 px-2 py-1 select-none" role="tablist">
        <div className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto scrollbar-none">
          {tabs.map((t) => {
            const isActive = t.id === activeTab.id

            return (
              <div
                aria-selected={isActive}
                className={cn(
                  'flex h-[26px] max-w-[140px] shrink-0 items-center gap-1 rounded-control border border-transparent px-2 text-xs transition-colors',
                  isActive
                    ? 'border-aro-line bg-aro-raise font-medium text-aro-ink shadow-aro-e1'
                    : 'text-aro-ink-3 hover:bg-aro-hover hover:text-aro-ink-2',
                )}
                key={t.id}
                role="tab"
              >
                <button
                  aria-label={t.url || 'New tab'}
                  className="flex min-w-0 flex-1 items-center gap-1.5 truncate text-left"
                  onClick={() => {
                    setActiveId(t.id)
                    setInputVal(t.input)
                    setError('')
                  }}
                  type="button"
                >
                  <IconGlobe className={cn('shrink-0', isActive ? 'text-aro-iris-soft' : 'text-aro-ink-4')} size={11} />
                  <span className="truncate">{t.title || 'New tab'}</span>
                </button>
                <button
                  aria-label={`Close ${t.title || 'tab'}`}
                  className="flex size-3.5 shrink-0 items-center justify-center rounded-control text-aro-ink-4 hover:bg-aro-hover hover:text-aro-rose"
                  onClick={(e) => {
                    e.stopPropagation()
                    handleCloseTab(t.id)
                  }}
                  type="button"
                >
                  <IconX size={9} />
                </button>
              </div>
            )
          })}
          <Tip label="New tab">
            <button
              aria-label="New browser tab"
              className="flex size-[24px] shrink-0 items-center justify-center rounded-control text-aro-ink-4 transition-colors hover:bg-aro-hover hover:text-aro-ink"
              onClick={handleNewTab}
              type="button"
            >
              <IconPlus size={12} />
            </button>
          </Tip>
        </div>
      </div>

      {/* URL Toolbar + Controls */}
      <div className="flex flex-wrap shrink-0 items-center gap-2 border-b border-aro-line-soft bg-aro-raise/40 px-3 py-1.5">
        <input
          aria-label="Preview URL"
          className="h-[26px] min-w-[140px] flex-1 rounded-control border border-aro-line-soft bg-aro-sunken px-2 font-aro-mono text-xs text-aro-ink outline-none placeholder:text-aro-ink-4"
          onChange={(e) => setInputVal(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              handleOpenUrl()
            }
          }}
          placeholder="https://example.com or localhost:3000"
          type="text"
          value={inputVal}
        />
        <Button
          disabled={!inputVal.trim()}
          onClick={() => handleOpenUrl()}
          size="xs"
          variant="outline"
        >
          Open
        </Button>

        {/* Quick Dev Server Presets */}
        <div className="hidden sm:flex items-center gap-1">
          {DEV_SERVER_PRESETS.map((preset) => (
            <Tip key={preset.url} label={`${preset.url} (${preset.hint})`}>
              <button
                className="rounded-control border border-aro-line-soft bg-aro-sunken/80 px-1.5 py-0.5 font-aro-mono text-[var(--aro-text-2xs,10px)] text-aro-ink-3 transition-colors hover:bg-aro-hover hover:text-aro-ink"
                onClick={() => {
                  setInputVal(preset.url)
                  handleOpenUrl(preset.url)
                }}
                type="button"
              >
                {preset.label}
              </button>
            </Tip>
          ))}
        </div>

        {activeTab.url && (
          <>
            <Tip label="Reload">
              <button
                aria-label="Reload preview"
                className="flex size-7 shrink-0 items-center justify-center rounded-control text-aro-ink-3 transition-colors hover:bg-aro-hover hover:text-aro-ink"
                onClick={handleReload}
                type="button"
              >
                <IconRefresh size={12} />
              </button>
            </Tip>
            <Tip label={copied ? 'Copied URL!' : 'Copy URL'}>
              <button
                aria-label={copied ? 'Copied URL!' : 'Copy preview URL'}
                className="flex size-7 shrink-0 items-center justify-center rounded-control text-aro-ink-3 transition-colors hover:bg-aro-hover hover:text-aro-ink"
                onClick={handleCopyUrl}
                type="button"
              >
                {copied ? <IconCheck className="text-aro-mint" size={12} /> : <IconCopy size={12} />}
              </button>
            </Tip>
          </>
        )}

        {/* Responsive Viewport Switchers */}
        <div aria-label="Viewport size" className="flex items-center gap-0.5 rounded-control border border-aro-line-soft bg-aro-sunken p-0.5" role="group">
          {VIEWPORTS.map((v) => (
            <Tip key={v.id} label={v.label}>
              <button
                aria-label={`${v.label} viewport`}
                aria-pressed={viewport === v.id}
                className={cn(
                  'flex size-6 items-center justify-center rounded-control text-aro-ink-4 transition-colors',
                  viewport === v.id ? 'bg-aro-raise text-aro-ink shadow-aro-e1' : 'hover:text-aro-ink-2',
                )}
                onClick={() => handleSetViewport(v.id)}
                type="button"
              >
                <v.icon size={12} />
              </button>
            </Tip>
          ))}
        </div>

        {activeTab.url && (
          <Tip label="Open in external browser">
            <button
              aria-label="Open externally"
              className="flex size-7 shrink-0 items-center justify-center rounded-control text-aro-ink-3 transition-colors hover:bg-aro-hover hover:text-aro-ink"
              onClick={() => window.open(activeTab.url, '_blank', 'noopener,noreferrer')}
              type="button"
            >
              <IconExternal size={12} />
            </button>
          </Tip>
        )}
      </div>

      {error && (
        <div className="shrink-0 bg-aro-rose/10 px-3 py-1 font-aro-mono text-aro-xs text-aro-rose" role="alert">
          {error}
        </div>
      )}

      {/* Main Preview Stage */}
      <div className="min-h-0 flex-1 overflow-auto bg-aro-sunken/40">
        {activeTab.url ? (
          <div className="flex h-full min-h-0 flex-col">
            <p className="shrink-0 border-b border-aro-line-soft bg-aro-sunken/20 px-3 py-1 text-[var(--aro-text-2xs,10px)] text-aro-ink-4">
              Local preview tab. Some sites block embedded iframes (X-Frame-Options); use external open if blank.
            </p>
            <div className={cn('flex min-h-0 flex-1 justify-center p-2', viewport !== 'desktop' && 'items-start')}>
              <div
                className={cn(
                  'relative h-full transition-[width,transform]',
                  viewport === 'desktop'
                    ? 'w-full'
                    : 'max-w-full rounded-overlay border border-aro-line-strong bg-white shadow-aro-e3 overflow-hidden',
                )}
                style={
                  viewport !== 'desktop'
                    ? { width: VIEWPORTS.find((v) => v.id === viewport)?.width }
                    : undefined
                }
              >
                <iframe
                  className="h-full w-full border-0 bg-white"
                  key={`${activeTab.id}-${reloadNonce}`}
                  referrerPolicy="no-referrer"
                  sandbox="allow-scripts allow-forms allow-same-origin"
                  src={activeTab.url}
                  title={`${activeTab.title || 'Page'} preview`}
                />
              </div>
            </div>
          </div>
        ) : (
          <div className="flex h-full min-h-[220px] flex-col items-center justify-center p-6 text-center">
            <div className="flex size-10 items-center justify-center rounded-overlay border border-aro-line-soft bg-aro-raise text-aro-ink-3 shadow-aro-e1">
              <IconEye size={18} />
            </div>
            <h3 className="mt-3 font-aro-display text-sm font-semibold text-aro-ink">No page open</h3>
            <p className="mt-1 max-w-[260px] text-xs leading-relaxed text-aro-ink-3">
              Enter a URL above or pick a local dev-server preset to launch responsive preview.
            </p>
            <div className="mt-4 flex flex-wrap justify-center gap-1.5">
              {DEV_SERVER_PRESETS.map((preset) => (
                <button
                  className="rounded-control border border-aro-line-soft bg-aro-raise px-2 py-1 font-aro-mono text-[var(--aro-text-2xs,10px)] text-aro-ink-2 transition-colors hover:border-aro-iris/60 hover:text-aro-ink"
                  key={preset.url}
                  onClick={() => {
                    setInputVal(preset.url)
                    handleOpenUrl(preset.url)
                  }}
                  type="button"
                >
                  Launch {preset.label}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default AroBrowserPreview
